let rafId;
function initFracturedPlanet() {

  /* ---------- starfield ---------- */
  const canvas = document.getElementById("stars");
const ctx = canvas.getContext("2d");
  let stars = [];
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function resize() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    stars = [];
    var count = Math.floor((canvas.width * canvas.height) / 9000);
    for (var i = 0; i < count; i++) {
      stars.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        r: Math.random() * 1.3 + 0.3,
        base: Math.random() * 0.5 + 0.25,
        speed: Math.random() * 1.5 + 0.4,
        phase: Math.random() * Math.PI * 2
      });
    }
  }
  function drawStars(t) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (var i = 0; i < stars.length; i++) {
      var s = stars[i];
      var tw = reduced ? 1 : (0.6 + 0.4 * Math.sin(t * 0.001 * s.speed + s.phase));
      ctx.globalAlpha = s.base * tw;
      ctx.fillStyle = '#cfe8ff';
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  /* ---------- rock plates ---------- */
  var planet = document.getElementById('planet');
  var logoWrap = document.getElementById('logoWrap');

  // ── ONE-SHOT SEQUENCE (no repeat) ─────────────────────────────
  var state = 'idle';

  function resetFragments(instant) {
    for (var i = 0; i < frags.length; i++) {
      frags[i].el.classList.remove('fadeout');
      frags[i].tgt = 0;
      if (instant) {
        frags[i].cur = 0;
        frags[i].el.style.transform = 'translate(0,0) rotate(0deg) scale(1)';
        frags[i].el.style.filter = '';
      }
      if (frags[i].glowEl) {
        frags[i].glowEl.style.transition = '';
        frags[i].glowEl.style.opacity = "0";
      }
    }
  }

 function showGlobe() {
  const innerEl = document.getElementById("inner");
  const pulse = document.getElementById("pulse");
  const glows = document.getElementById("glows");

  if (!innerEl || !pulse || !glows) return;

  innerEl.style.transition = "opacity 1.1s ease";
  pulse.style.transition = "opacity 1.1s ease";
  glows.style.transition = "opacity 1.1s ease";

  innerEl.style.opacity = "1";
  pulse.style.opacity = "";
  glows.style.opacity = "1";
}

function hideGlobe() {
  const innerEl = document.getElementById("inner");
  const pulse = document.getElementById("pulse");
  const glows = document.getElementById("glows");

  if (!innerEl || !pulse || !glows) return;

  innerEl.style.transition = "opacity 0.8s ease";
  pulse.style.transition = "opacity 0.8s ease";
  glows.style.transition = "opacity 0.8s ease";

  innerEl.style.opacity = "0";
  pulse.style.opacity = "0";
  glows.style.opacity = "0";
}

 function runSequence() {
  // PHASE 1 — BLAST: all rocks fly outward
  state = 'blasting';
  mouseOn = false;
  for (var i = 0; i < frags.length; i++) {
    frags[i].tgt = 0.80 + Math.random() * 0.20;
  }

  // PHASE 2 — 2.2s: rocks have flown out, now hold them there 1.5s
  setTimeout(function () {
    // PHASE 3 — after 1.5s hold, fade globe base
    hideGlobe();

    // PHASE 4 — stagger-fade each fragment one by one (random order)
    var indices = frags.map(function(_, i){ return i; });
    // shuffle
    for (var s = indices.length - 1; s > 0; s--) {
      var r = Math.floor(Math.random() * (s + 1));
      var tmp = indices[s]; indices[s] = indices[r]; indices[r] = tmp;
    }
    var staggerDelay = 120; // ms between each fragment fade
    var totalFadeTime = indices.length * staggerDelay + 600;

    indices.forEach(function(fragIdx, order) {
      setTimeout(function() {
        var f = frags[fragIdx];
        f.el.style.transition =
          'opacity 0.55s ease, transform 1.1s cubic-bezier(0.2,0.8,0.3,1), ' +
          'filter 0.55s ease';
        f.el.style.opacity = '0';
        if (f.glowEl) {
          f.glowEl.style.transition = 'opacity 0.4s ease';
          f.glowEl.style.opacity = '0';
        }
      }, order * staggerDelay);
    });

    // PHASE 5 — after all fragments faded + 0.8s gap → logo rises and stays,
    // then redirect to /welcome
    setTimeout(function () {
      if (!logoWrap) return;
      state = 'logoVisible';
      logoWrap.classList.add('visible');

      // Redirect after logo is shown
      setTimeout(function () {
        window.location.assign('/welcome');
      }, 1500);
    }, totalFadeTime + 800);

  }, 2200);
}

  // start after 1.5s initial pause
  setTimeout(runSequence, 1500);


  var holder = document.getElementById('frags');
  var glowHolder = document.getElementById('glows');
  var pulse = document.getElementById('pulse');
  var innerEl = document.getElementById('inner');

  if (!planet || !logoWrap || !holder || !glowHolder || !pulse || !innerEl) {
    return;
  }
  
  var frags = PLATES.map(function (p) {
    var poly = 'polygon(' + p.poly.map(function (pt) {
      return pt[0] + '% ' + pt[1] + '%';
    }).join(', ') + ')';

    // shoelace area for overlap tie-breaking and glow sizing
    var area = 0;
    for (var i = 0, j = p.poly.length - 1; i < p.poly.length; j = i++) {
      area += (p.poly[j][0] + p.poly[i][0]) * (p.poly[j][1] - p.poly[i][1]);
    }
    area = Math.abs(area / 2);

    // centroid of the plate in % coords
    var cx = 0, cy = 0;
    p.poly.forEach(function (pt) { cx += pt[0]; cy += pt[1]; });
    cx /= p.poly.length; cy /= p.poly.length;

    var el = document.createElement('div');
    el.className = 'frag';
    el.style.clipPath = poly;
    el.style.webkitClipPath = poly;
    el.style.transformOrigin = cx + '% ' + cy + '%';
    holder.appendChild(el);

    // light burst behind this rock, sized to the rock itself
    var rp = Math.sqrt(area / Math.PI);            // plate radius in %
    var gr = Math.min(30, Math.max(9, rp * 2.4));  // glow radius in %
    var glowEl = document.createElement('div');
    glowEl.className = 'glow';
    glowEl.style.background =
      'radial-gradient(ellipse ' + gr.toFixed(1) + '% ' + gr.toFixed(1) + '% at ' +
      cx.toFixed(2) + '% ' + cy.toFixed(2) + '%, ' +
      'rgba(255,255,255,0.95) 0%, ' +
      'rgba(190,235,255,0.85) 22%, ' +
      'rgba(90,180,255,0.45) 48%, ' +
      'rgba(30,110,255,0.15) 70%, ' +
      'transparent 100%)';
    if (glowHolder) {
      glowHolder.appendChild(glowEl);
    }

    return {
      el: el,
      glowEl: glowEl,
      area: area,
      cx: cx, cy: cy,
      ux: p.ux, uy: p.uy,
      d: p.d,
      maxDist: (reduced ? 8 : 17) + p.d * (reduced ? 6 : 12),  // % of planet size — slightly increased spread
      maxRot: (Math.random() - 0.5) * 12,
      // zero-gravity floating while separated
      fAmp: 0.7 + Math.random() * 0.8,           // float amplitude in %
      fx: 0.6 + Math.random() * 0.7,             // float speeds (rad/s)
      fy: 0.5 + Math.random() * 0.7,
      fr: 0.4 + Math.random() * 0.6,
      px: Math.random() * 6.283,                 // phases
      py: Math.random() * 6.283,
      pr: Math.random() * 6.283,
      cur: 0,        // current influence 0..1
      tgt: 0         // target influence 0..1
    };
  });

  /* ---------- hit logic: only the rock under the cursor breaks ---------- */
  var mouseOn = false;
  var mx = 50, my = 50;
  var forceAll = false;    // keyboard/touch-toggle fallback

  function pointInPoly(x, y, poly) {
    var inside = false;
    for (var i = 0, j = poly.length - 1; i < poly.length; j = i++) {
      var xi = poly[i][0], yi = poly[i][1];
      var xj = poly[j][0], yj = poly[j][1];
      if (((yi > y) !== (yj > y)) &&
          (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) {
        inside = !inside;
      }
    }
    return inside;
  }

  var AREA_RADIUS = 12;     // % of planet size: local hover area
  var PCX = 50.08, PCY = 50.03, PR = 44.67;  // planet center and radius in % coords

  function setTargets() {
    if (state !== 'idle') return;
    var hit = -1;
    if (mouseOn && !forceAll) {
      var bestArea = Infinity;
      for (var i = 0; i < frags.length; i++) {
        if (pointInPoly(mx, my, PLATES[i].poly)) {
          var a = frags[i].area;
          if (a < bestArea) { bestArea = a; hit = i; }
        }
      }
    }

    // cursor position relative to planet center
    var cdx = mx - PCX, cdy = my - PCY;
    var cDist = Math.sqrt(cdx * cdx + cdy * cdy);
    var cRad = cDist / PR;                       // 0 = dead center, 1 = edge
    var ucx = cDist > 0.001 ? cdx / cDist : 0;   // cursor direction unit vector
    var ucy = cDist > 0.001 ? cdy / cDist : 0;

    // SIDE MODE: cursor near the edge -> that whole side fans open
    var sideFactor = Math.max(0, Math.min(1, (cRad - 0.40) / 0.35));

    for (var k = 0; k < frags.length; k++) {
      var f = frags[k];
      if (forceAll)      { f.tgt = 1; continue; }
      if (!mouseOn)      { f.tgt = 0; continue; }

      // 1) local area around the cursor
      var dx = f.cx - mx, dy = f.cy - my;
      var dist = Math.sqrt(dx * dx + dy * dy);
      var g = Math.exp(-(dist * dist) / (2 * AREA_RADIUS * AREA_RADIUS));
      if (k === hit) g = 1;

      // 2) edge hover -> every rock on that side fans outward
      if (sideFactor > 0) {
        var cos = f.ux * ucx + f.uy * ucy;       // is this rock on the cursor's side?
        if (cos > 0) {
          var side = sideFactor * Math.pow(cos, 2.0) * (0.45 + 0.55 * f.d);
          if (side > g) g = side;
        }
      }

      f.tgt = (g < 0.05) ? 0 : g;
    }
  }

  function updatePointer(clientX, clientY) {
    if (!planet) return;
    var rect = planet.getBoundingClientRect();
    mx = ((clientX - rect.left) / rect.width) * 100;
    my = ((clientY - rect.top) / rect.height) * 100;
    mouseOn = true;
    setTargets();
  }




  /* ---------- animation loop: smooth easing toward targets ---------- */
  function tick(t) {
    drawStars(t);

    var active = 0;
    for (var i = 0; i < frags.length; i++) {
      var f = frags[i];
      f.cur += (f.tgt - f.cur) * 0.09;
      if (f.cur < 0.001 && f.tgt === 0) f.cur = 0;
      if (f.cur > active) active = f.cur;

      var d = f.cur * f.maxDist;
      var sec = t * 0.001;
      // gentle zero-gravity floating while the rock is separated
      var floatOn = reduced ? 0 : f.cur;
      var flx = Math.sin(sec * f.fx + f.px) * f.fAmp * floatOn;
      var fly = Math.cos(sec * f.fy + f.py) * f.fAmp * floatOn;
      var flr = Math.sin(sec * f.fr + f.pr) * 2.5 * floatOn;
      var r = f.cur * f.maxRot + flr;
      var s = 1 + 0.06 * f.cur;                      // lift toward viewer
      f.el.style.transform =
        'translate(' + (f.ux * d + flx).toFixed(3) + '%, ' + (f.uy * d + fly).toFixed(3) + '%) ' +
        'rotate(' + r.toFixed(3) + 'deg) ' +
        'scale(' + s.toFixed(4) + ')';
      f.el.style.filter =
        'brightness(' + (1 + 0.35 * f.cur).toFixed(3) + ') ' +
        'saturate(' + (1 + 0.45 * f.cur).toFixed(3) + ')';
      var breathe = 1 + (reduced ? 0 : 0.12 * Math.sin(sec * 1.4 + f.px));
      f.glowEl.style.opacity = (Math.pow(f.cur, 1.15) * breathe).toFixed(3);
    }

    // hide the whole-image pulse overlay while rocks are displaced
    // show logo when enough rocks are displaced (planet ~50% broken)
    var totalBreak = 0;
    for (var bi = 0; bi < frags.length; bi++) totalBreak += frags[bi].cur;
    var avgBreak = frags.length > 0 ? totalBreak / frags.length : 0;
    if (avgBreak > 0.042) logoWrap?.classList.add('visible');
    else logoWrap?.classList.remove('visible');

    if (active > 0.05) pulse?.classList.add('quiet');
    else pulse?.classList.remove('quiet');

    // the energy core blazes harder as the rocks open up
    innerEl?.style.setProperty('filter',
      'brightness(' + (0.92 + 0.55 * active).toFixed(3) + ') ' +
      'saturate(' + (1 + 0.25 * active).toFixed(3) + ')');

    rafId = requestAnimationFrame(tick);
  }

  window.addEventListener('resize', resize);
  resize();
  rafId = requestAnimationFrame(tick);

  return function cleanup() {
    window.removeEventListener('resize', resize);
    if (rafId) cancelAnimationFrame(rafId);
  };
}

(function () {
  App.ready.then(function () {
    var visited = false;
    try { visited = localStorage.getItem("visited") === "true"; } catch (e) {}
    if (visited) { window.location.replace("/dashboard"); return; }
    App.hideLoader();
    initFracturedPlanet();
  });
})();
